with ranked as (select * from (select *, row_number() over (partition by category order by launch_date desc nulls last, id asc) as dedup_rank from products) x where dedup_rank = 1) select case when cost >= 720 then 'PREMIUM' else 'STANDARD' end as cost_tier, sum(case when category = 'Books' then stock_qty else 0 end) as books_stock_qty, sort_array(collect_set(brand)) as brand_list, min(cost) as min_cost, sort_array(collect_set(category)) as category_list, count(distinct id) as distinct_ids, size(collect_set(brand)) as num_brands from ranked group by case when cost >= 720 then 'PREMIUM' else 'STANDARD' end order by min_cost desc nulls last;
